$limit=(int)$config['sync_limit'];$log=$pdo->prepare('INSERT INTO sync_logs(status,message) VALUES(?,?)');$log->execute(['running','Jikan synchronization started']);$done=0;
for($page=1;$page<=2;$page++){ $ctx=stream_context_create(['http'=>['timeout'=>15,'header'=>'User-Agent: AniRead/1.0']]);$raw=@file_get_contents($config['jikan_base'].'/top/anime?page='.$page, false,$ctx);if(!$raw)continue;$json=json_decode($raw,true);foreach(($json['data']??[]) as $x){$i=$x['mal_id']??null;if(!$i)continue;$sql='INSERT INTO anime(mal_id,anilist_id,title,english_title,japanese_title,synopsis,poster,banner,trailer_url,type,status,episodes,duration,score,rank,popularity,members,favorites,year,season,source,studio,aired_from,aired_to) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),english_title=VALUES(english_title),synopsis=VALUES(synopsis),poster=VALUES(poster),banner=VALUES(banner),score=VALUES(score),updated_at=NOW()';$v=[$i,null,$x['title']??'Untitled',$x['title_english']??null,$x['title_japanese']??null,$x['synopsis']??null,$x['images']['jpg']['large_image_url']??null,$x['images']['jpg']['large_image_url']??null,$x['trailer']['url']??null,$x['type']??null,$x['status']??null,$x['episodes']??null,$x['duration']??null,$x['score']??null,$x['rank']??null,$x['popularity']??null,$x['members']??null,$x['favorites']??null,$x['year']??null,$x['season']??null,$x['source']??null,null,$x['aired']['from']?substr($x['aired']['from'],0,10):null,$x['aired']['to']?substr($x['aired']['to'],0,10):null];$pdo->prepare($sql)->execute($v);$aid=$pdo->lastInsertId();if(!$aid){$q=$pdo->prepare('SELECT id FROM anime WHERE mal_id=?');$q->execute([$i]);$aid=$q->fetchColumn();}foreach(($x['genres']??[]) as $g){$pdo->prepare('INSERT IGNORE INTO genres(name) VALUES(?)')->execute([$g['name']]);$q=$pdo->prepare('SELECT id FROM genres WHERE name=?');$q->execute([$g['name']]);$gid=$q->fetchColumn();$pdo->prepare('INSERT IGNORE INTO anime_genres VALUES(?,?)')->execute([$aid,$gid]);}$done++;}sleep(1);}$log=$pdo->prepare('INSERT INTO sync_logs(status,message,finished_at) VALUES(?,?,NOW())');$log->execute(['success',"Synchronized {$done} anime records"]);echo "Synchronized {$done} anime records\n";
